import {fresh,step,center,TUNE,ROUTE_LENGTH} from './road.js';
import {Renderer} from './renderer.js';
// Input, fixed-step loop, pause/focus handling, preferences and sound evolve 006.
const $=s=>document.querySelector(s), canvas=$('#view'),speedEl=$('#speed'),pause=$('#pause'),overlay=$('#overlay');
let renderer,fatal=false;function fail(message){fatal=true;$('#error-message').textContent=message;$('#error').hidden=false;release();if(raf)cancelAnimationFrame(raf);raf=0;state.paused=true;quietAudio()}
let preferences={gentle:false,motion:matchMedia('(prefers-reduced-motion: reduce)').matches,quality:false,volume:.18,camera:'chase'};
try{let p=JSON.parse(localStorage.getItem('cityFarePrefs')||'{}');for(let k of ['gentle','motion','quality'])if(typeof p[k]==='boolean')preferences[k]=p[k];if(Number.isFinite(p.volume))preferences.volume=Math.max(0,Math.min(1,p.volume));if(p.camera==='wide')preferences.camera='wide'}catch(e){}
const STEP=1/60,MAX_STEPS=5,MPH=2.236936;let state=fresh(),previous={...state},held=new Set(),pointers=new Map(),last=0,accumulator=0,raf=0,started=false,overloads=0,lastChapter=-1,toastTimer;
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'gas',KeyW:'gas',ArrowDown:'brake',KeyS:'brake',Space:'brake'};
function actions(){const a={left:false,right:false,gas:false,brake:false};for(const code of held)if(keyMap[code])a[keyMap[code]]=true;for(const action of pointers.values())a[action]=true;return a}
function paintInputs(){const a=actions();document.querySelectorAll('.drive').forEach(b=>b.classList.toggle('on',!!a[b.dataset.key]))}
function release(){held.clear();pointers.clear();paintInputs()}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
// A new launch always starts at mile zero; remove the superseded prototype save.
try{localStorage.removeItem('cityFareSonoranSave007')}catch(e){}
function savePreferences(){try{localStorage.setItem('cityFarePrefs',JSON.stringify(preferences))}catch(e){}}
function render(interpolate=false,dt=STEP){if(!renderer)return;let visible=state;if(interpolate){let a=accumulator/STEP;visible={...state};for(let k of ['x','v','steer','angle','distance'])visible[k]=previous[k]+(state[k]-previous[k])*a;visible.z=previous.z+(state.z-previous.z)*a}renderer.render(visible,preferences,dt,actions());speedEl.textContent=Math.round(state.v*MPH);$('#speedbar').style.width=(state.v/TUNE.maxSpeed*100)+'%';$('#distance').textContent=Math.max(0,(ROUTE_LENGTH-state.distance)/1609.344).toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1});$('#progress').style.width=(state.distance/ROUTE_LENGTH*100)+'%';let fade=Math.max(0,Math.min(1,(state.distance-(ROUTE_LENGTH-2500))/2500));$('#finish-fade').style.opacity=state.finished?1:Math.pow(fade,1.7)*.85;if(state.finished){release();quietAudio();document.body.classList.add('finished');$('#finish').hidden=false}updateAudio()}
function frame(t){raf=0;if(!started||state.paused)return;if(!last)last=t;let elapsed=(t-last)/1000;last=t;if(elapsed>.35){setPaused(true);return}accumulator+=Math.max(0,elapsed);let steps=0;while(accumulator>=STEP&&steps<MAX_STEPS){previous={...state};step(state,actions(),STEP,preferences);accumulator-=STEP;steps++}if(accumulator>=STEP){overloads++;accumulator%=STEP}render(true,elapsed);if(!state.finished)raf=requestAnimationFrame(frame)}
function setPaused(value){if(!started||fatal||state.finished)return;state.paused=value;overlay.hidden=!value;pause.innerHTML=value?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';pause.setAttribute('aria-label',value?'Resume drive':'Pause and settings');release();last=0;accumulator=0;previous={...state};if(value){quietAudio();if(raf)cancelAnimationFrame(raf);raf=0;render();$('#resume').focus()}else{if(!raf)raf=requestAnimationFrame(frame);pause.focus()}}
function toggle(){if(started)setPaused(!state.paused)}
function start(){if(started||fatal)return;started=true;state.paused=false;document.body.classList.remove('intro');document.body.classList.add('playing');$('#welcome').inert=true;$('#drivehud').inert=false;$('.controls').inert=false;last=0;raf=requestAnimationFrame(frame);pause.focus()}
function resetDrive(){if(fatal)return;document.body.classList.remove('finished');$('#finish').hidden=true;$('#finish-fade').style.opacity=0;state=fresh();previous={...state};renderer.yaw=null;lastChapter=-1;release();if(!started)start();setPaused(false);render();}
$('#again').onclick=resetDrive;$('#start').onclick=start;pause.onclick=toggle;$('#resume').onclick=()=>setPaused(false);$('#restart').onclick=resetDrive;$('.brand').onclick=e=>{e.preventDefault();if(started)setPaused(true)};
$('#camera span').textContent=preferences.camera==='wide'?'Wide cam':'Chase cam';
$('#camera').onclick=()=>{preferences.camera=preferences.camera==='wide'?'chase':'wide';savePreferences();$('#camera span').textContent=preferences.camera==='wide'?'Wide cam':'Chase cam';render();};
for(const name of ['gentle','motion','quality']){let el=$('#'+name);el.checked=preferences[name];el.onchange=()=>{preferences[name]=el.checked;savePreferences();if(name==='quality')renderer.resize(preferences.quality);render()}}
let volume=$('#volume');volume.value=preferences.volume;volume.oninput=()=>{preferences.volume=Number(volume.value);savePreferences();updateAudio()};

// Gesture-started electric motor: soft sine pair and filtered air, no gear drone.
let audio=null,osc=null,gain=null,wind=null,windGain=null,harmonic=null,soundOn=false;
function quietAudio(){if(audio&&gain){gain.gain.setTargetAtTime(0,audio.currentTime,.08);windGain.gain.setTargetAtTime(0,audio.currentTime,.08)}}
function updateAudio(){if(!audio)return;let active=soundOn&&!state.paused&&!state.finished&&started,a=actions(),ratio=state.v/TUNE.maxSpeed;osc.frequency.setTargetAtTime(55+state.v*1.65+(a.gas?4:0),audio.currentTime,.25);harmonic.frequency.setTargetAtTime(110+state.v*3.3,audio.currentTime,.3);gain.gain.setTargetAtTime(active?preferences.volume*(.008+ratio*.025):0,audio.currentTime,.16);windGain.gain.setTargetAtTime(active?preferences.volume*ratio*.045:0,audio.currentTime,.3)}
$('#sound').onclick=async()=>{try{if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('unavailable');audio=new AC();gain=audio.createGain();gain.gain.value=0;gain.connect(audio.destination);osc=audio.createOscillator();osc.type='sine';osc.connect(gain);osc.start();harmonic=audio.createOscillator();harmonic.type='sine';let hg=audio.createGain();hg.gain.value=.16;harmonic.connect(hg);hg.connect(gain);harmonic.start();let buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;wind=audio.createBufferSource();wind.buffer=buffer;wind.loop=true;let filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=380;windGain=audio.createGain();windGain.gain.value=0;wind.connect(filter);filter.connect(windGain);windGain.connect(audio.destination);wind.start()}soundOn=!soundOn;if(soundOn)await audio.resume();$('#sound').textContent='Sound: '+(soundOn?'On':'Off');if(!soundOn)quietAudio()}catch(e){soundOn=false;$('#sound').textContent='Sound unavailable'}};
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.code==='Tab'&&!overlay.hidden){let items=[...overlay.querySelectorAll('button,input')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}return}if(keyMap[e.code]){e.preventDefault();if(started&&!state.paused){held.add(e.code);paintInputs()}}if(!e.repeat){if(e.code==='KeyP'||e.code==='Escape')toggle();if(e.code==='KeyC'&&started&&overlay.hidden)$('#camera').click();if(e.code==='KeyR'&&started&&overlay.hidden)resetDrive()}});
window.addEventListener('keyup',e=>{if(keyMap[e.code]){held.delete(e.code);paintInputs()}});
document.querySelectorAll('.drive').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(!started||state.paused)return;b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,b.dataset.key);paintInputs()});function up(e){pointers.delete(e.pointerId);paintInputs()}for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,up)});
window.addEventListener('blur',()=>{release();if(started&&!state.paused)setPaused(true)});window.addEventListener('pagehide',()=>{release();if(started&&!state.paused)setPaused(true)});document.addEventListener('visibilitychange',()=>{if(document.hidden){release();if(started&&!state.paused)setPaused(true)}});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();fail('The graphics connection was interrupted. Reload to restart the drive.')});window.addEventListener('error',e=>fail('The drive stopped unexpectedly. Please reload.'));window.addEventListener('resize',()=>{if(renderer){renderer.resize(preferences.quality);render()}});
try{renderer=new Renderer(canvas);renderer.resize(preferences.quality);render()}catch(e){fail(e.message)}
// Read-only diagnostics. No debug teleport/control mutations are exposed.
window.CityFare=Object.freeze({inspect:()=>({version:'007-Sonoran-Run',fatal,state:{...state},input:actions(),preferences:{...preferences},started,overloads,graphics:renderer?.inspect()||null})});
